import os, json, urllib.request

REPO = "/home/etudiants/info/ibrahim/tp1-Ilyes-BRAHIM"
env = {}
with open(os.path.join(REPO, ".env")) as f:
    for line in f:
        line = line.strip()
        if line and "=" in line and not line.startswith("#"):
            k, v = line.split("=", 1)
            env[k.strip()] = v.strip()
cfg = json.load(open(os.path.join(REPO, "opencode.json")))
BASE = cfg["mcp"]["bibliotheque"]["url"]
TOKEN = env["BIBLIO_TOKEN"]


def _rpc(payload, session=None):
    data = json.dumps(payload).encode()
    req = urllib.request.Request(BASE, data=data, method="POST")
    req.add_header("Content-Type", "application/json")
    req.add_header("Accept", "application/json, text/event-stream")
    req.add_header("Authorization", "Bearer " + TOKEN)
    if session:
        req.add_header("Mcp-Session-Id", session)
    with urllib.request.urlopen(req, timeout=30) as r:
        return r.headers.get("Mcp-Session-Id"), r.read().decode()


def _parse(body):
    for line in body.splitlines():
        if line.startswith("data:"):
            d = json.loads(line[5:])
            if "error" in d:
                return {"_error": d["error"]}
            txt = d["result"]["content"][0]["text"]
            try:
                return json.loads(txt)
            except Exception:
                return {"_raw": txt}
    return {"_error": "no data", "_body": body[:500]}


def call(tool, args):
    sid, _ = _rpc({"jsonrpc": "2.0", "id": 1, "method": "initialize",
                   "params": {"protocolVersion": "2025-06-18", "capabilities": {},
                              "clientInfo": {"name": "tp1", "version": "1.0"}}})
    # send initialized notification
    try:
        _rpc({"jsonrpc": "2.0", "method": "notifications/initialized"}, session=sid)
    except Exception:
        pass
    _, body = _rpc({"jsonrpc": "2.0", "id": 2, "method": "tools/call",
                    "params": {"name": tool, "arguments": args}}, session=sid)
    return _parse(body)


def fetch_all(tool, args):
    out = []
    start = None
    while True:
        a = dict(args)
        if start:
            a["start_key"] = start
        r = call(tool, a)
        if "items" not in r:
            print("ERR", tool, r)
            break
        out.extend(r["items"])
        nxt = r.get("next")
        if not nxt or nxt == start:
            break
        start = nxt
    return out

